<script setup>
</script>
<template>
  <div class="relative">
    <!-- Compact status bar view -->
    <div
      class="flex items-center gap-1 cursor-pointer hover:bg-base-200 rounded px-1 py-0.5"
      @click="togglePanel"
    >
      <!-- Avatar -->
      <div class="avatar placeholder">
        <div class="w-6 h-6 rounded-full bg-neutral text-neutral-content overflow-hidden">
          <img v-if="user?.avatar" :src="user.avatar" :alt="user?.userName" class="w-full h-full object-cover" />
          <span v-else class="text-xs">{{ userInitial }}</span>
        </div>
      </div>
      <!-- Compact cost badge -->
      <div v-if="todayMetrics" class="text-xs text-warning font-mono hidden sm:flex items-center gap-0.5">
        <span>{{ formatCoins(todayMetrics.total_cxjcoins) }}</span>
        <span class="opacity-60">cxj</span>
      </div>
    </div>

    <!-- Detailed panel overlay -->
    <div
      v-if="showPanel"
      class="absolute right-0 top-8 z-50 w-80 bg-base-200 border border-base-300 rounded-lg shadow-xl p-4 flex flex-col gap-3"
    >
      <!-- Header: user info -->
      <div class="flex items-center gap-3">
        <div class="avatar placeholder">
          <div class="w-12 h-12 rounded-full bg-neutral text-neutral-content overflow-hidden">
            <img v-if="user?.avatar" :src="user.avatar" :alt="user?.userName" class="w-full h-full object-cover" />
            <span v-else class="text-lg">{{ userInitial }}</span>
          </div>
        </div>
        <div>
          <div class="font-semibold text-base-content">{{ user?.userName }}</div>
          <div class="text-xs text-base-content opacity-60">{{ user?.role }}</div>
        </div>
        <button class="btn btn-xs btn-ghost ml-auto" @click="showPanel = false">✕</button>
      </div>

      <div class="divider my-0"></div>

      <!-- Loading state -->
      <div v-if="loading" class="flex justify-center py-2">
        <span class="loading loading-spinner loading-sm"></span>
      </div>

      <template v-else-if="metrics">
        <!-- Today metrics -->
        <div>
          <div class="text-xs font-bold text-base-content opacity-70 uppercase mb-1">Today</div>
          <div class="grid grid-cols-2 gap-1 text-xs">
            <MetricRow label="Calls" :value="metrics.today.calls" />
            <MetricRow label="Tokens" :value="formatTokens(metrics.today.total_tokens)" />
            <MetricRow label="Input" :value="formatTokens(metrics.today.input_tokens)" />
            <MetricRow label="Output" :value="formatTokens(metrics.today.output_tokens)" />
            <MetricRow label="Duration" :value="formatDuration(metrics.today.total_duration_seconds)" />
            <MetricRow label="CXJ Coins" :value="formatCoins(metrics.today.total_cxjcoins)" highlight />
          </div>
        </div>

        <div class="divider my-0"></div>

        <!-- Current month metrics -->
        <div>
          <div class="text-xs font-bold text-base-content opacity-70 uppercase mb-1">
            This Month
            <span class="font-normal normal-case opacity-60 ml-1">{{ metrics.current_month.start_date }} → {{ metrics.current_month.end_date }}</span>
          </div>
          <div class="grid grid-cols-2 gap-1 text-xs">
            <MetricRow label="Calls" :value="metrics.current_month.calls" />
            <MetricRow label="Tokens" :value="formatTokens(metrics.current_month.total_tokens)" />
            <MetricRow label="Input" :value="formatTokens(metrics.current_month.input_tokens)" />
            <MetricRow label="Output" :value="formatTokens(metrics.current_month.output_tokens)" />
            <MetricRow label="Duration" :value="formatDuration(metrics.current_month.total_duration_seconds)" />
            <MetricRow label="CXJ Coins" :value="formatCoins(metrics.current_month.total_cxjcoins)" highlight />
          </div>
        </div>
      </template>

      <div v-else class="text-xs text-base-content opacity-50 text-center py-2">No metrics available</div>

      <!-- Logout -->
      <div class="divider my-0"></div>
      <button class="btn btn-xs btn-outline btn-error w-full" @click="logout">Logout</button>
    </div>

    <!-- Backdrop to close panel -->
    <div v-if="showPanel" class="fixed inset-0 z-40" @click="showPanel = false"></div>
  </div>
</template>
<script>
// Inline helper sub-component rendered via render trick — use a simple span-based display
const MetricRow = {
  props: ['label', 'value', 'highlight'],
  template: `
    <div class="flex justify-between items-center bg-base-100 rounded px-2 py-0.5">
      <span class="opacity-60">{{ label }}</span>
      <span :class="highlight ? 'text-warning font-bold font-mono' : 'font-mono'">{{ value }}</span>
    </div>
  `
}

export default {
  components: { MetricRow },
  data() {
    return {
      showPanel: false,
      loading: false
    }
  },
  computed: {
    user() {
      return this.$storex.users.user
    },
    metrics() {
      return this.$storex.users.metrics
    },
    todayMetrics() {
      return this.metrics?.today
    },
    userInitial() {
      return (this.user?.userName || '?')[0].toUpperCase()
    }
  },
  methods: {
    async togglePanel() {
      this.showPanel = !this.showPanel
      if (this.showPanel && !this.metrics) {
        await this.fetchMetrics()
      }
    },
    async fetchMetrics() {
      this.loading = true
      try {
        await this.$storex.users.loadMetrics()
      } catch(e) {
        // silently fail
      } finally {
        this.loading = false
      }
    },
    formatCoins(val) {
      return val != null ? Number(val).toFixed(2) : '-'
    },
    formatTokens(val) {
      if (val == null) return '-'
      if (val >= 1_000_000) return (val / 1_000_000).toFixed(1) + 'M'
      if (val >= 1_000) return (val / 1_000).toFixed(1) + 'K'
      return val
    },
    // Convert seconds to human readable hh:mm:ss
    formatDuration(seconds) {
      if (seconds == null) return '-'
      const h = Math.floor(seconds / 3600)
      const m = Math.floor((seconds % 3600) / 60)
      const s = Math.floor(seconds % 60)
      if (h > 0) return `${h}h ${m}m`
      if (m > 0) return `${m}m ${s}s`
      return `${s}s`
    },
    async logout() {
      this.showPanel = false
      await this.$storex.users.logout()
    }
  }
}
</script>
